/// <summary>
/// MPJ_2863_Nathan AR Inv Acknowledgment 
/// Extension of Postload and creation of new method to get the METGSTAmount
/// </summary>
[ExtensionOf(tableStr(FreeTextInvoiceEntity))]
public final class METFreeTextInvoiceEntity_Extension
{

}

Method.Source:
    /// <summary>
    /// CoC extension
    /// </summary>
    /// <param name = "_dmfDefinitionGroupExecution">_dmfDefinitionGroupExecution</param>
    public static void preTargetProcessSetBased(DMFDefinitionGroupExecution _dmfDefinitionGroupExecution)
    {
        ttsbegin;

        next preTargetProcessSetBased(_dmfDefinitionGroupExecution);

        ProjFundingSource       fundingSource;
        FreeTextInvoiceStaging  staging;

        while select forupdate staging
            where   staging.DefinitionGroup         == _dmfDefinitionGroupExecution.DefinitionGroup
            &&      staging.ExecutionId             == _dmfDefinitionGroupExecution.ExecutionId
            &&      (staging.TransferStatus         == DMFTransferStatus::NotStarted || staging.TransferStatus == DMFTransferStatus::Validated)
            &&      staging.METProjFundingSourceId  != ''
        outer join RecID from fundingSource
            where   fundingSource.CustAccount       == staging.CustomerAccount
            &&      fundingSource.FundingSourceID   == staging.METProjFundingSourceID
        {
            boolean ok = true;

            if(!fundingSource.RecId) // change if query filter on metProjFundingSourceID removed.
            {
                error(strFmt("@MET:ProjFundingSourceNotExistForCust",
                    staging.METProjFundingSourceId,
                    staging.CustomerAccount));
                ok = false;
            }

            if(!ok)
            {
                staging.TransferStatus = DMFTransferStatus::Error;
                staging.update();
            }
        }

        ttscommit;
        
    }

    /// <summary>
    /// CoC extension
    /// </summary>
    /// <param name = "_dmfDefinitionGroupExecution">_dmfDefinitionGroupExecution</param>
    /// <param name = "_sourceDocumentFTIMap">_sourceDocumentFTIMap</param>
    /// <param name = "_dimCacheTmpHeaderDefaultDimension">_dimCacheTmpHeaderDefaultDimension</param>
    protected static void insertFreeTextInvoiceHeaderV2(
        DMFDefinitionGroupExecution _dmfDefinitionGroupExecution,
        FreeTextInvoiceSourceDocumentHeaderStaging _sourceDocumentFTIMap,
        DimensionDataEntitySFKCacheTmp _dimCacheTmpHeaderDefaultDimension)
    {
        next insertFreeTextInvoiceHeaderV2(
            _dmfDefinitionGroupExecution,
            _sourceDocumentFTIMap,
            _dimCacheTmpHeaderDefaultDimension);

        FreeTextInvoiceStaging  staging;
        CustInvoiceTable        custInvoiceTable;
        CustTable               custTable;
        DictTable               dictTable = new DictTable(tableNum(CustInvoiceTable));
        DictField               dictField;

        FreeTextInvoiceEntity::skipTableMethods(custInvoiceTable, true);
               
        // Row-by-row update of header. No easy way to apply all logic in initFromCustTable
        // without duplicating a large amount of logic with multiple set-based updates.
        // Alternative is to update fields in staging table prior to insert.
        while select forupdate custInvoiceTable
        join staging
            where   custInvoiceTable.InvoiceId      == staging.FreeTextNumber
            &&      staging.DefinitionGroup         == _dmfDefinitionGroupExecution.DefinitionGroup
            &&      staging.ExecutionId             == _dmfDefinitionGroupExecution.ExecutionId
            &&      (staging.TransferStatus         == DMFTransferStatus::NotStarted || staging.TransferStatus == DMFTransferStatus::Validated)
        join custTable
            where   custTable.AccountNum            == custInvoiceTable.OrderAccount
        exists join _sourceDocumentFTIMap
            where _sourceDocumentFTIMap.FreeTextNumber == staging.FreeTextNumber
               && _sourceDocumentFTIMap.SourceDocumentHeader == custInvoiceTable.SourceDocumentHeader
        {
            custInvoiceTable.METImported = true;

            // Determine fields that have already been populated.
            Map populatedFieldsMap = new Map(Types::String, Types::AnyType);    // <fieldName, value>

            int fieldIdx;
            for(fieldIdx = 1; fieldIdx <= dictTable.fieldCnt(); fieldIdx++)
            {
                dictField = new DictField(tableNum(CustInvoiceTable), dictTable.fieldCnt2Id(fieldIdx));
                if(dictField.arraySize() == 1 && custInvoiceTable.(dictField.id()))
                {
                    populatedFieldsMap.insert(dictField.name(), custInvoiceTable.(dictField.id()));
                }
            }

            // Default initFromCust logic.
            custInvoiceTable.initFromCustTable(custTable);
            // CS added for CFR4 bulkApproveARInvoice -->
            custInvoiceTable.METDMFImportFileName    = _dmfDefinitionGroupExecution.fileName(); 
            custInvoiceTable.METRecipientEmail       = staging.METRecipientEmail;
            custInvoiceTable.CustomerInvoiceOriginId = staging.METInvoiceOriginType;
            // CE added for CFR4 bulkApproveARInvoice <--

            // Replace values that had already been populated.
            MapEnumerator mapEnum = populatedFieldsMap.getEnumerator();
            while(mapEnum.moveNext())
            {
                int fieldID = fieldName2Id(tableNum(CustInvoiceTable), mapEnum.currentKey());
                custInvoiceTable.(fieldID) = mapEnum.currentValue();
            }

            // Update
            if(!bufCmp(custInvoiceTable, custInvoiceTable.orig()))
            {
                custInvoiceTable.update();
            }
        }       
    }

    /// <summary>
    /// CoC extension
    /// </summary>
    /// <param name = "_dmfDefinitionGroupExecution">_dmfDefinitionGroupExecution</param>
    /// <param name = "_sourceDocumentFTIMap">_sourceDocumentFTIMap</param>
    /// <param name = "_dimCacheTmpLedgerAccount">_dimCacheTmpLedgerAccount</param>
    /// <param name = "_dimCacheTmpDefaultDimension">_dimCacheTmpDefaultDimension</param>
    protected static void insertFreeTextInvoiceLines(
        DMFDefinitionGroupExecution _dmfDefinitionGroupExecution,
        FreeTextInvoiceSourceDocumentHeaderStaging _sourceDocumentFTIMap,
        DimensionDataEntitySFKCacheTmp _dimCacheTmpLedgerAccount,
        DimensionDataEntitySFKCacheTmp _dimCacheTmpDefaultDimension)
    {
        next insertFreeTextInvoiceLines(
            _dmfDefinitionGroupExecution,
            _sourceDocumentFTIMap,
            _dimCacheTmpLedgerAccount,
            _dimCacheTmpDefaultDimension);
    
        // MPJ-9755
        FreeTextInvoiceEntity::metUpdateInvoiceLinesAdditionalDetails(
            _dmfDefinitionGroupExecution, 
            _sourceDocumentFTIMap); 

    }

    static private void metUpdateInvoiceLinesAdditionalDetails(
    DMFDefinitionGroupExecution                 _definitionGroupExecution,
    FreeTextInvoiceSourceDocumentHeaderStaging  _sourceDocumentFTIMap)
    {
        // MPJ-9755
        CustInvoiceTable        custInvoiceTable;
        CustInvoiceLine         custInvoiceLine, custInvoiceLineUpdate;
        SourceDocumentLine      sourceDocumentLine;
        ProjTable               projTable;
        FreeTextInvoiceStaging  staging;
        Set                     lineRecIDs = new Set(Types::Int64); // <CustInvoiceLine.RecID>

        DimensionHierarchy      dimHierarchy;
        DimensionHierarchyLevel dimHierarchyLevel;
        container               defaultDimensionAttributes;
        container               defaultDimensionValues;
        DimensionDefault        defaultDimension;
    
        // Find order of attributes applicable from the integration/entity hierarchy.
        dimHierarchy = DimensionHierarchy::findByTypeAndName(DimensionHierarchyType::DataEntityDefaultDimensionFormat, 'Default dimension format');   // name is fixed, sys-defined.
        if(dimHierarchy)
        {
            while select dimHierarchyLevel
            order by Level
            where   dimHierarchyLevel.DimensionHierarchy == dimHierarchy.RecId
            {
                DimensionAttribute attr = DimensionAttribute::find(dimHierarchyLevel.DimensionAttribute);
                if(attr.Name != 'MainAccount')
                {
                    defaultDimensionAttributes += attr.Name;
                }
            }

            while select custInvoiceLine
                join custInvoiceTable
                where custInvoiceTable.RecId            == custInvoiceLine.ParentRecId
                join staging
                    where staging.DefinitionGroup     == _definitionGroupExecution.DefinitionGroup
                        && staging.ExecutionId         == _definitionGroupExecution.ExecutionId
                        && staging.LineNumber          == custInvoiceLine.LineNum
                        && staging.CustomerAccount     == custInvoiceTable.InvoiceAccount
            {
                select firstonly forupdate custInvoiceLineUpdate
                    where custInvoiceLineUpdate.RecId == custInvoiceLine.RecId;

                if(custInvoiceLineUpdate.RecId
                    && staging.DEFAULTDIMENSIONDISPLAYVALUE
                            && staging.DEFAULTDIMENSIONDISPLAYVALUE != '')
                {                            
                    ttsbegin;
                    defaultDimensionValues = str2con(staging.DEFAULTDIMENSIONDISPLAYVALUE, '-');          
                    defaultDimension = FreeTextInvoiceEntity::getOrCreateDefaultDimension(defaultDimensionAttributes, defaultDimensionValues);
                    custInvoiceLineUpdate.DefaultDimension = defaultDimension ? defaultDimension : CustTable::find(custInvoiceTable.InvoiceAccount).DefaultDimension;

                    custInvoiceLineUpdate.doUpdate();
                    ttscommit;                    
                }
            }
        }
        else
        {
            while select custInvoiceLine
          join custInvoiceTable
              where   custInvoiceTable.RecId                      == custInvoiceLine.ParentRecId
          join staging
              where   staging.DefinitionGroup                     == _definitionGroupExecution.DefinitionGroup
              &&      staging.ExecutionId                         == _definitionGroupExecution.ExecutionId
              &&      staging.LineNumber                          == custInvoiceLine.LineNum
              &&      staging.CustomerAccount                     == custInvoiceTable.InvoiceAccount
            {
                select firstonly forupdate custInvoiceLineUpdate
                where custInvoiceLineUpdate.RecId == custInvoiceLine.RecId;

                if(custInvoiceLineUpdate.RecId)
                {
                    ttsbegin;
                    custInvoiceLineUpdate.DefaultDimension = CustTable::find(custInvoiceTable.InvoiceAccount).DefaultDimension;
                
                    // Set the AccountCur value if value is null at the time of insert entity
                    if (staging.AmountCur == 0)
                    {
                        custInvoiceLineUpdate.AmountCur = staging.Quantity * staging.UnitPrice;
                    }
                    custInvoiceLineUpdate.doUpdate();
                    ttscommit;
                }
            }
        }

        ttsbegin;
        while select forupdate custInvoiceLine
    join custInvoiceTable
        where   custInvoiceTable.RecId                      == custInvoiceLine.ParentRecId
    join sourceDocumentLine
        where   sourceDocumentLine.SourceDocumentHeader     == custInvoiceTable.SourceDocumentHeader
    join staging
        where   staging.DefinitionGroup                     == _definitionGroupExecution.DefinitionGroup
        &&      staging.ExecutionId                         == _definitionGroupExecution.ExecutionId
        &&      staging.LineNumber                          == custInvoiceLine.LineNum
        &&      staging.CustomerReference                   == custInvoiceTable.CustomerRef
        &&      staging.CustomerReference                   != ''
       
        &&      (staging.METProjId != '' || staging.METReasonCode != '')
        &&      staging.CustomerAccount                     == custInvoiceTable.InvoiceAccount

    outer join projTable
        where   projTable.ProjId                            == staging.METProjId
    exists join _sourceDocumentFTIMap
        where _sourceDocumentFTIMap.SourceDocumentHeader    == sourceDocumentLine.SourceDocumentHeader
        {
            if(lineRecIDs.in(custInvoiceLine.RecId))
            {
                continue;
            }
            lineRecIDs.add(custInvoiceLine.RecId);
            if(projTable)
            {
                DimensionAttributeValueSetStorage   dimStorageInvoiceLine, dimStorageProject;
                DimensionAttribute                  dimAttribute;
                DimensionValue                      currentValue, projectAttrValue;
                int                                 attrIdx;

                dimStorageInvoiceLine   = DimensionAttributeValueSetStorage::find(custInvoiceLine.DefaultDimension);
                dimStorageProject       = DimensionAttributeValueSetStorage::find(projTable.DefaultDimension);

                for(attrIdx = 1; attrIdx <= conLen(defaultDimensionAttributes); attrIdx++)
                {
                    str attrName        = conPeek(defaultDimensionAttributes, attrIdx);
                    dimAttribute        = DimensionAttribute::findByName(attrName);
                    currentValue        = dimStorageInvoiceLine.getDisplayValueByDimensionAttribute(dimAttribute.RecId);
                    projectAttrValue    = dimStorageProject.getDisplayValueByDimensionAttribute(dimAttribute.RecId);

                    //if(projectAttrValue)
                    if(!currentValue) // req 19/10, dims can be overridden by import
                    {
                        dimStorageInvoiceLine.addItem(DimensionAttributeValue::findByDimensionAttributeAndValue(dimAttribute, projectAttrValue, true, true));
                    }
                }

                custInvoiceLine.DefaultDimension    = dimStorageInvoiceLine.save();
                custInvoiceLine.ProjId              = staging.METProjId;
                custInvoiceLine.ProjCategoryId      = staging.METProjCategoryId;

                if(staging.METProjFundingSourceID)
                {
                    // ** Confirm relation for ProjFundingSource.. Contract ID?
                    ProjFundingSource fundingSource;
                    select firstonly RecId from fundingSource
                    order by RecId desc
                    where   fundingSource.CustAccount       == custInvoiceTable.InvoiceAccount
                    &&      fundingSource.FundingSourceID   == staging.METProjFundingSourceID;

                    custInvoiceLine.ProjFundingSource = fundingSource.RecID;
                }
            } // projTable exists

            if(staging.METReasonCode)
            {
                ReasonTableRef reasonRef;
                reasonRef.Reason        = staging.METReasonCode;
                reasonRef.ReasonComment = staging.METReasonComment;

                if(!reasonRef.ReasonComment)
                {
                    reasonRef.ReasonComment = ReasonTable::find(reasonRef.Reason).Description;
                }

                reasonRef.insert();
                custInvoiceLine.ReasonRefRecId = reasonRef.RecId;
            }

            if(!bufCmp(custInvoiceLine, custInvoiceLine.orig()))
            {
                custInvoiceLine.doUpdate();
            }
        }
        ttscommit;
    }

/// <summary>
/// MPJ_2863_Nathan AR Inv Acknowledgment
/// populating METGSTAmount
/// </summary>
public void postLoad()
{
    next postload();
    this.METGSTAmount = this.getMETGSTAmount();
}

    /// <summary>
    /// MPJ_2863_Nathan AR Inv Acknowledgment
    /// Get GST amount from custinvoicejour
    /// Could not add data source from data entity due to  foreign key thus virtual field was created.
    /// </summary> 
    /// <returns>TaxAmount returns METGSTAmount</returns>
    public TaxAmount getMETGSTAmount()
    {
        TaxAmount taxAmount = 0;
        TaxTrans taxTrans;
        CustInvoiceJour custInvoiceJour;
                
        if (this.FreeTextNumber)
        {
            select firstonly LedgerVoucher, InvoiceId from custInvoiceJour
                join Voucher, TaxCode, SourceRegulateAmountCur from taxTrans
                    where taxTrans.Voucher == custInvoiceJour.LedgerVoucher
                       && custInvoiceJour.InvoiceId == this.FreeTextNumber
                       && taxTrans.TaxCode == this.SalesTaxGroup;

            if (taxTrans)
            {
                taxAmount = -taxTrans.SourceRegulateAmountCur;
            }
        }

        return taxAmount;
    }

/// <summary>
/// Returns No or yes if its volumteric rebate deal
/// </summary>
/// <returns>Returns no or yes</returns>
private static str isVolumetricRebateDeal()
{
    return SysComputedColumn::returnField(
        tableStr(FreeTextInvoiceEntity),
        dataEntityDataSourceStr(FreeTextInvoiceEntity, CustInvoiceTable),
        fieldStr(CustInvoiceTable, METVolumetricTierDeal));
}

    /// <summary>
    /// Performs a custom copy from the staging table to the target environment.
    /// </summary>
    /// <param name = "_dmfDefinitionGroupExecution">The definition group.</param>
    /// <returns>A container of counts of [new records, updated records].</returns>
    /// Added for CFR4 bulk approval AR invoice.
    public static container copyCustomStagingToTarget(DMFDefinitionGroupExecution _dmfDefinitionGroupExecution)
    {
        ttsbegin;
        FreeTextInvoiceEntity::validateInvoiceOrigin(_dmfDefinitionGroupExecution);
        ttscommit;

        container completedRecords = next copyCustomStagingToTarget(_dmfDefinitionGroupExecution);

        return completedRecords;
    }

    /// <summary>
    /// Validate free text invoice origin.
    /// </summary>
    /// <param name = "_dmfDefinitionGroupExecution">Contains definition group.</param>
    /// Added for CFR4 bulk approval AR invoice
    public static void validateInvoiceOrigin(DMFDefinitionGroupExecution _dmfDefinitionGroupExecution)
    {
        FreeTextInvoiceStaging      staging;
        FreeTextInvoiceStagingTmp   freeTextInvoiceStagingError;
        CustomerInvoiceOrigin       customerInvoiceOrigin;
        DMFExecutionId              executionId = _dmfDefinitionGroupExecution.ExecutionId;
        DMFDefinitionGroupName      executionGroup = _dmfDefinitionGroupExecution.DefinitionGroup;
        TableName                   entityName = _dmfDefinitionGroupExecution.Entity;

        freeTextInvoiceStagingError.skipBusinessEvents(true);
        freeTextInvoiceStagingError.skipDataMethods(true);

        insert_recordset freeTextInvoiceStagingError
            (FreeTextNumber, METInvoiceOriginType, DefinitionGroup, ExecutionId)
            select FreeTextNumber, METInvoiceOriginType, DefinitionGroup, ExecutionId
                from staging
                group by FreeTextNumber, METInvoiceOriginType, DefinitionGroup, ExecutionId
                where staging.METInvoiceOriginType != ''
                    && staging.DefinitionGroup == executionGroup
                    && staging.ExecutionId == executionId
                    && (staging.TransferStatus == DMFTransferStatus::NotStarted || staging.TransferStatus == DMFTransferStatus::Validated)
            notexists join customerInvoiceOrigin
                where customerInvoiceOrigin.OriginId == staging.METInvoiceOriginType;

        // Set the error status in staging table
        staging.skipBusinessEvents(true);
        staging.skipDataMethods(true);

        update_recordset staging
            setting
                TransferStatus = DMFTransferStatus::Error
            where staging.DefinitionGroup == executionGroup
                && staging.ExecutionId == executionId
                && (staging.TransferStatus == DMFTransferStatus::NotStarted || staging.TransferStatus == DMFTransferStatus::Validated)
                exists join freeTextInvoiceStagingError
                where freeTextInvoiceStagingError.FreeTextNumber   == staging.FreeTextNumber 
                    && freeTextInvoiceStagingError.METInvoiceOriginType == staging.METInvoiceOriginType;

        // Get the error message for each invoice failed to be imported
        while select METInvoiceOriginType
            from freeTextInvoiceStagingError
        join staging
            where staging.FreeTextNumber == freeTextInvoiceStagingError.FreeTextNumber
                && staging.METInvoiceOriginType == freeTextInvoiceStagingError.METInvoiceOriginType
        {
            ErrorMsg error = strFmt("@SYP4986038", fieldPName(FreeTextInvoiceStaging, METInvoiceOriginType), freeTextInvoiceStagingError.METInvoiceOriginType, tablePName(CustomerInvoiceOrigin));

            DMFStagingValidationLog::insertLogs(
                staging.DefinitionGroup,
                staging.ExecutionId,
                DMFEntity::find(entityName),
                staging.RecId,
                '',
                error,
                DMFSourceTarget::Target);
        }
    }

    /// <summary>
    /// Creates a default dimension from the supplied attribute names and values.
    /// Iterates the attribute names in <paramref name="_attributesContainer"/> and the
    /// corresponding values in <paramref name="_valuesContainer"/>. For each pair it
    /// looks up the DimensionAttribute and the matching DimensionAttributeValue. If all
    /// referenced attribute values are found, a DimensionAttributeValueSetStorage is
    /// built and saved and the resulting DimensionDefault is returned. If any attribute
    /// value is missing, no default dimension is created and the method returns 0.
    /// </summary>
    /// <param name = "_attributesContainer">Container of dimension attribute names (ordered).</param>
    /// <param name = "_valuesContainer">Container of corresponding display values (ordered).</param>
    /// <returns>Returns the created <see cref="DimensionDefault"/> when successful; otherwise 0.</returns>
    public static DimensionDefault getOrCreateDefaultDimension(container _attributesContainer, container _valuesContainer)
    {
        DimensionAttributeValueSetStorage dimStorage = new DimensionAttributeValueSetStorage();
        DimensionAttribute      dimAttr;
        DimensionAttributeValue dimAttrValue;
        DimensionDefault        defaultDimension;
        boolean                 isValid = true;
        int                     i;
 
        for (i = 1; i <= conLen(_attributesContainer); i++)
        {
            dimAttr = DimensionAttribute::findByName(conPeek(_attributesContainer, i));

            if (dimAttr.RecId
                && conPeek(_valuesContainer, i) != '')
            {
                dimAttrValue = DimensionAttributeValue::findByDimensionAttributeAndValue(dimAttr, conPeek(_valuesContainer, i), false, false);

                if (dimAttrValue.RecId)
                {
                    dimStorage.addItem(dimAttrValue);
                }
                else
                {
                    isValid = false;
                    break; // If any attribute value is not found, do not create a new default dimension.
                }
            }
        }
    
        if(isValid)
        {
            defaultDimension = dimStorage.save();
        }

        return defaultDimension;
    }
